/* Platform marks for the SEO orrery, in their own brand colours, on a
   24×24 grid. Sources: simple-icons (CC0) for DuckDuckGo, Google Maps,
   Yelp and Apple; @lobehub/icons (MIT) for Google, Bing, ChatGPT, Gemini,
   Perplexity and Claude (simple-icons no longer carries the OpenAI and
   Microsoft marks). Each is the brand's own shape, used only to name the
   platform. "reviews" is drawn here, not a brand mark.
   Rendered two ways: in colour on the orbiting planets, and as one-colour
   glyphs (fill: currentColor) in the discipline list. */

export type MarkKey =
  | "google"
  | "bing"
  | "duckduckgo"
  | "chatgpt"
  | "gemini"
  | "perplexity"
  | "claude"
  | "googlemaps"
  | "yelp"
  | "apple"
  | "reviews";

export type MarkGradient = {
  id: string;
  /** coordinates on the 24 grid (userSpaceOnUse) instead of 0–1 */
  user?: boolean;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  /** [offset, colour, opacity?] */
  stops: [number, string, number?][];
};

export type Mark = {
  /** fill-rule for compound paths (most AI marks punch holes) */
  evenodd?: boolean;
  paths: { d: string; fill: string }[];
  gradients?: MarkGradient[];
};

